/*
 Problem: 3734. Lexicographically Smallest Palindromic Permutation Greater Than Target
 Language: cpp
 Runtime: 3 ms (72.16%)
 Memory: 11.2 MB (75.26%)
 Tags: Two Pointers, String, Enumeration
*/
class Solution {
public:
    string lexPalindromicPermutation(string s, string target) {
        int n = s.size(), h = n / 2;
        vector<int> f(26);

        for (const auto& c : s) ++f[c - 'a'];

        char mid = 0;
        for (int i = 0; i < 26; ++i) {
            if (f[i] & 1) {
                if (mid) return "";
                mid = 'a' + i;
                --f[i];
            }
        }

        for (int i = 0; i < h; ++i)
            f[target[i] - 'a'] -= 2;

        auto build = [&](string l) {
            string r = l;
            reverse(r.begin(), r.end());
            if (mid) l += mid;
            return l + r;
        };

        if (check(f)) {
            string l = target.substr(0, h);
            string cur = build(l);
            if (cur > target) return cur;
        }

        for (int i = h - 1; i >= 0; --i) {
            f[target[i] - 'a'] += 2;

            if (!check(f)) continue;

            for (int j = target[i] - 'a' + 1; j < 26; ++j) {
                if (f[j] < 2) continue;

                f[j] -= 2;

                string l = target.substr(0, i);
                l += 'a' + j;

                for (int k = 0; k < 26; ++k)
                    l.append(f[k] / 2, 'a' + k);

                return build(l);
            }
        }

        return "";
    }

    bool check(const vector<int>& f) {
        for (const auto& x : f) if (x < 0) return false;
        return true;
    }
};
